<?php
declare(strict_types=1);
require_once __DIR__.'/recurrence_policy.php';
require_once __DIR__.'/mail_mime.php';require_once __DIR__.'/mail_remote.php';
function gszMailSync(PDO $pdo,GszMailRemote $remote,string $folder,int $limit=50):array {
 if((int)$pdo->query("SELECT GET_LOCK('gsz_mail_sync',1)")->fetchColumn()!==1)throw new RuntimeException('Synchronisation läuft bereits.');
 try{$folders=$remote->folders();if(!in_array($folder,$folders,true))throw new RuntimeException('Ordner unbekannt.');foreach($folders as $name){if(mb_strlen($name)>190)continue;$pdo->prepare('INSERT IGNORE INTO mail_folders(name) VALUES(?)')->execute([$name]);}
  $q=$pdo->prepare('SELECT * FROM mail_folders WHERE name=?');$q->execute([$folder]);$local=$q->fetch();$valid=$remote->validity($folder);$last=(int)$local['uidvalidity']===$valid?(int)$local['last_uid']:0;$items=$remote->fetchAfter($folder,$last,max(1,min(100,$limit)));usort($items,fn($a,$b)=>(int)$a['uid']<=>(int)$b['uid']);if($remote->validity($folder)!==$valid)throw new RuntimeException('UIDVALIDITY während Abruf geändert. Neu synchronisieren.');
  $refresh=[];if($remote instanceof GszMailFlagRemote){$q=$pdo->prepare('SELECT remote_uid FROM mail_messages WHERE folder_id=? AND uidvalidity=? AND active=1 ORDER BY remote_uid DESC LIMIT 100');$q->execute([$local['id'],$valid]);$refresh=$remote->flags($folder,$q->fetchAll(PDO::FETCH_COLUMN));if($remote->validity($folder)!==$valid)throw new RuntimeException('UIDVALIDITY beim Flag-Abruf geändert.');}
  $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM mail_folders WHERE id=? FOR UPDATE');$q->execute([$local['id']]);$locked=$q->fetch();if((int)$locked['uidvalidity']!==$valid)$pdo->prepare('UPDATE mail_messages SET active=0 WHERE folder_id=?')->execute([$local['id']]);$created=0;$rules=$pdo->query('SELECT * FROM mail_rules WHERE active=1 ORDER BY id')->fetchAll();
   foreach($items as $item){if((int)$item['uid']<1||(int)$item['uid']<=$last)continue;$m=gszMimeParse($item['raw']);$important=false;foreach($rules as $r)if(str_contains(mb_strtolower($m['sender']),mb_strtolower($r['sender_pattern'])))$important=(bool)$r['important'];
    $q=$pdo->prepare('SELECT id FROM mail_messages WHERE folder_id=? AND uidvalidity=? AND remote_uid=?');$q->execute([$local['id'],$valid,$item['uid']]);$id=$q->fetchColumn();
    if(!$id){$pdo->prepare('INSERT INTO mail_messages(folder_id,uidvalidity,remote_uid,message_id,sender,recipients,subject,sent_at,body,seen,important,automatic_message,reply_to,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$local['id'],$valid,$item['uid'],$m['message_id'],mb_substr($m['sender'],0,500),$m['recipients'],mb_substr($m['subject'],0,500),$m['sent_at'],$m['body'],$item['seen']?1:0,$important?1:0,$m['automatic']?1:0,mb_substr($m['reply_to'],0,500),!empty($item['deleted'])?0:1]);$id=(int)$pdo->lastInsertId();$created++;foreach($m['attachments'] as $a){$file=gszStoreBytes('mail',$a['data']);$pdo->prepare('INSERT IGNORE INTO mail_attachments(message_id,original_name,mime_type,stored_name,size_bytes,sha256) VALUES(?,?,?,?,?,?)')->execute([$id,$a['name'],mb_substr($a['mime'],0,100),$file['stored_name'],$file['size_bytes'],$file['sha256']]);}}
    $last=max($last,(int)$item['uid']);
   }
   foreach($refresh as $uid=>$flag)$pdo->prepare('UPDATE mail_messages SET seen=?,active=? WHERE folder_id=? AND uidvalidity=? AND remote_uid=?')->execute([$flag['seen']?1:0,$flag['missing']?0:1,$local['id'],$valid,$uid]);
   $pdo->prepare('UPDATE mail_folders SET uidvalidity=?,last_uid=?,last_sync=UTC_TIMESTAMP(),last_error=\'\' WHERE id=?')->execute([$valid,$last,$local['id']]);gszAudit($pdo,null,'mail_sync',['folder_id'=>(int)$local['id'],'created'=>$created]);$pdo->commit();return ['created'=>$created,'last_uid'=>$last,'limited'=>count($items)>=max(1,min(100,$limit))||(method_exists($remote,'morePending')&&$remote->morePending())];
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
 }catch(Throwable $e){try{$pdo->prepare("UPDATE mail_folders SET last_error='Synchronisation fehlgeschlagen; Verbindung/UID/Größenlimit prüfen' WHERE name=?")->execute([$folder]);}catch(Throwable $ignored){}throw $e;}finally{$pdo->query("SELECT RELEASE_LOCK('gsz_mail_sync')");}
}
function gszMailMessage(PDO $pdo,int $id):array {$q=$pdo->prepare('SELECT m.*,f.name folder_name FROM mail_messages m JOIN mail_folders f ON f.id=m.folder_id WHERE m.id=?');$q->execute([$id]);return $q->fetch()?:throw new RuntimeException('Nachricht nicht gefunden.');}
function gszMailRemoteAction(PDO $pdo,GszMailRemote $remote,int $admin,int $id,string $action,string $target=''):void {
 $m=gszMailMessage($pdo,$id);if(!$m['active']||$remote->validity($m['folder_name'])!==(int)$m['uidvalidity'])throw new RuntimeException('Nachrichtenidentität veraltet. Neu synchronisieren.');
 if($action==='seen'||$action==='unseen'){$seen=$action==='seen';$remote->seen($m['folder_name'],(int)$m['remote_uid'],$seen);$pdo->prepare('UPDATE mail_messages SET seen=? WHERE id=?')->execute([$seen?1:0,$id]);}
 elseif($action==='move'){if($target===$m['folder_name'])throw new InvalidArgumentException('Zielordner muss sich vom Quellordner unterscheiden.');$remote->move($m['folder_name'],(int)$m['remote_uid'],$target);$pdo->prepare('UPDATE mail_messages SET active=0 WHERE id=?')->execute([$id]);}
 else throw new InvalidArgumentException('Mailaktion unbekannt.');gszAudit($pdo,$admin,'mail_'.$action,['message_id'=>$id]);
}
function gszMailSaveDraft(PDO $pdo,array $input,?int $id=null):int {
 $to=(string)($input['to_address']??'');$cc=(string)($input['cc_address']??'');gszMailAddresses($to);gszMailAddresses($cc);$bcc=(string)($input['bcc_address']??'');gszMailAddresses($bcc);if($bcc!==''&&!gszV1Ready($pdo))throw new RuntimeException('BCC benötigt Migration340.');$subject=trim((string)($input['subject']??''));$body=(string)($input['body']??'');if(mb_strlen($subject)>190||preg_match('/[\r\n]/',$subject)||strlen($body)>150000)throw new InvalidArgumentException('Entwurf zu groß oder Betreff ungültig.');$reply=(int)($input['reply_message_id']??0);$header='';if($reply)$header=gszMailMessage($pdo,$reply)['message_id'];
 $pdo->beginTransaction();try{if($id){$q=$pdo->prepare('SELECT status FROM mail_drafts WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetchColumn();if(!in_array($old,['draft','rejected'],true))throw new RuntimeException('Versandstand gesperrt. Kein stiller Neuversand.');$pdo->prepare("UPDATE mail_drafts SET to_address=?,cc_address=?,subject=?,body=?,status='draft',reply_message_id=?,reply_header=? WHERE id=?")->execute([$to,$cc,$subject,$body,$reply?:null,$header,$id]);}
 else{$pdo->prepare('INSERT INTO mail_drafts(to_address,cc_address,subject,body,reply_message_id,reply_header,message_id) VALUES(?,?,?,?,?,?,?)')->execute([$to,$cc,$subject,$body,$reply?:null,$header,'<'.bin2hex(random_bytes(16)).'@gsz.internal>']);$id=(int)$pdo->lastInsertId();}if(gszV1Ready($pdo))$pdo->prepare('UPDATE mail_drafts SET bcc_address=? WHERE id=?')->execute([$bcc,$id]);$pdo->commit();return $id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function gszMailDraftAttachment(PDO $pdo,int $id,string $name,string $bytes):void {
 $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT status FROM mail_drafts WHERE id=? FOR UPDATE');$q->execute([$id]);if($q->fetchColumn()!=='draft')throw new RuntimeException('Entwurf nicht bearbeitbar.');$q=$pdo->prepare('SELECT COUNT(*) count,SUM(size_bytes) total FROM mail_draft_attachments WHERE draft_id=?');$q->execute([$id]);$limits=$q->fetch();if((int)$limits['count']>=10||(int)$limits['total']+strlen($bytes)>10*1024*1024)throw new RuntimeException('Maximal 10 Anhänge und insgesamt 10 MB.');$file=gszStoreBytes('mail',$bytes);$mime=(new finfo(FILEINFO_MIME_TYPE))->buffer($bytes);$pdo->prepare('INSERT IGNORE INTO mail_draft_attachments(draft_id,original_name,mime_type,stored_name,size_bytes,sha256) VALUES(?,?,?,?,?,?)')->execute([$id,gszName($name),mb_substr($mime,0,100),$file['stored_name'],$file['size_bytes'],$file['sha256']]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function gszMailSendDraft(PDO $pdo,GszMailSender $sender,?GszMailRemote $remote,int $admin,int $id,string $from,string $sentFolder):string {
 return gszMailDraftLock($pdo,$id,function()use($pdo,$sender,$remote,$admin,$id,$from,$sentFolder):string {
 $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM mail_drafts WHERE id=? FOR UPDATE');$q->execute([$id]);$draft=$q->fetch();if(!$draft)throw new RuntimeException('Entwurf fehlt.');if($draft['status']==='accepted'){$pdo->commit();return 'accepted';}if($draft['status']!=='draft')throw new RuntimeException('Versand unklar/gesperrt. Postfach prüfen, kein automatisches Wiederholen.');if(strlen($sentFolder)>190||preg_match('/[\x00\r\n]/',$sentFolder))throw new RuntimeException('Gesendet-Ziel ungültig.');$q=$pdo->prepare('SELECT * FROM mail_draft_attachments WHERE draft_id=? ORDER BY id');$q->execute([$id]);$attachments=[];foreach($q->fetchAll() as $a)$attachments[]=['name'=>$a['original_name'],'data'=>gszReadBytes('mail',$a['stored_name'],$a['sha256'])];$built=gszBuildMail($draft,$from,$attachments);$pdo->prepare("UPDATE mail_drafts SET status='sending',smtp_raw=?,smtp_raw_sha256=?,sent_copy_folder=?,sent_copy_uidvalidity=0,sent_copy_uid=NULL,sent_copy_uncertain=0,sent_copy=0 WHERE id=?")->execute([$built['raw'],hash('sha256',$built['raw']),$sentFolder,$id]);gszAudit($pdo,$admin,'mail_send_requested',['draft_id'=>$id]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
 try{$sender->send($built['recipients'],$built['raw']);}
 catch(Throwable $e){$status=$e instanceof GszMailSendException&&!$e->uncertain?'rejected':'uncertain';$pdo->prepare('UPDATE mail_drafts SET status=?,last_error=? WHERE id=?')->execute([$status,'SMTP-Annahme nicht bestätigt; vor Wiederholung prüfen',$id]);gszAudit($pdo,$admin,'mail_send_'.$status,['draft_id'=>$id]);throw new RuntimeException('SMTP-Annahme nicht bestätigt. Entwurfstatus prüfen; nicht blind erneut senden.');}
 $pdo->prepare("UPDATE mail_drafts SET status='accepted',last_error='' WHERE id=?")->execute([$id]);if($draft['reply_message_id'])$pdo->prepare('UPDATE mail_messages SET answered=1 WHERE id=?')->execute([$draft['reply_message_id']]);gszAudit($pdo,$admin,'mail_smtp_accepted',['draft_id'=>$id]);
 if($remote&&$sentFolder!==''){try{
  $valid=$remote->validity($sentFolder);if($valid<1)throw new RuntimeException('UIDVALIDITY fehlt.');$pdo->prepare('UPDATE mail_drafts SET sent_copy_uidvalidity=? WHERE id=?')->execute([$valid,$id]);
  $existing=null;if($remote instanceof GszMailSearchRemote){$existing=gszMailRecoverySearch($remote,array_replace($draft,['sent_copy_folder'=>$sentFolder,'sent_copy_uidvalidity'=>$valid]));if($existing['result']==='conflict')throw new RuntimeException('Gesendet-Kopie mehrdeutig.');}
  if($existing&&$existing['result']==='found'){$pdo->prepare('UPDATE mail_drafts SET sent_copy=1,sent_copy_uid=? WHERE id=?')->execute([$existing['uids'][0],$id]);return 'accepted';}
  // Persist ambiguity BEFORE APPEND: a crash or lost acknowledgement must never look unattempted.
  $pdo->prepare('UPDATE mail_drafts SET sent_copy_uncertain=1 WHERE id=?')->execute([$id]);$remote->append($sentFolder,$built['raw']);if($remote->validity($sentFolder)!==$valid)throw new RuntimeException('Gesendet-Ordneridentität geändert.');$pdo->prepare('UPDATE mail_drafts SET sent_copy=1,sent_copy_uncertain=0 WHERE id=?')->execute([$id]);
 }catch(Throwable $e){$pdo->prepare("UPDATE mail_drafts SET last_error='SMTP angenommen, Gesendet-Kopie nicht bestätigt. Nur Kopie prüfen; nicht erneut senden.' WHERE id=?")->execute([$id]);}}
 return 'accepted';
 });
}
/** Serialize original send and recovery for this draft, without holding SQL row locks during network I/O. */
function gszMailDraftLock(PDO $pdo,int $id,callable $work):mixed {
 $name='gsz_mail_copy_'.substr(hash('sha256',(string)$pdo->query('SELECT DATABASE()')->fetchColumn().'|'.$id),0,40);$q=$pdo->prepare('SELECT GET_LOCK(?,1)');$q->execute([$name]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Versand-/Kopierprüfung läuft bereits.');
 try{return $work();}finally{$q=$pdo->prepare('SELECT RELEASE_LOCK(?)');$q->execute([$name]);}
}
function gszMailRecoveryDraft(PDO $pdo,int $id):array {
 $q=$pdo->prepare('SELECT * FROM mail_drafts WHERE id=?');$q->execute([$id]);$d=$q->fetch();if(!$d||$d['status']!=='accepted'||$d['sent_copy'])throw new RuntimeException('Nur eine fehlende Kopie nach bestätigter SMTP-Annahme prüfen.');
 if(!is_string($d['smtp_raw'])||$d['smtp_raw']===''||!preg_match('/^[a-f0-9]{64}$/D',$d['smtp_raw_sha256'])||!hash_equals($d['smtp_raw_sha256'],hash('sha256',$d['smtp_raw'])))throw new RuntimeException('Unverändertes Versandoriginal fehlt. Historische Nachrichten nicht nachbauen.');
 $header=gszMimeHeaders(preg_split('/\r?\n\r?\n/',$d['smtp_raw'],2)[0]);if(!preg_match('/^<[a-f0-9]{32}@gsz\.internal>$/D',$d['message_id'])||($header['message-id']??'')!==$d['message_id'])throw new RuntimeException('Versandidentität nicht bestätigt.');
 if($d['sent_copy_folder']===''||strlen($d['sent_copy_folder'])>190||preg_match('/[\x00\r\n]/',$d['sent_copy_folder']))throw new RuntimeException('Ursprüngliches Gesendet-Ziel fehlt.');return $d;
}
function gszMailRecoverySearch(GszMailRemote $remote,array $d):array {
 if(!$remote instanceof GszMailSearchRemote)throw new RuntimeException('Adapter unterstützt keine sichere Identitätssuche.');$folder=$d['sent_copy_folder'];if(!in_array($folder,$remote->folders(),true))throw new RuntimeException('Ursprünglicher Gesendet-Ordner fehlt.');$valid=$remote->validity($folder);if($valid<1)throw new RuntimeException('UIDVALIDITY fehlt.');
 $found=$remote->findMessageId($folder,$d['message_id']);if(($found['uidvalidity']??null)!==$valid||$remote->validity($folder)!==$valid)throw new RuntimeException('UIDVALIDITY während Kopierprüfung geändert.');
 foreach(['uids','deleted_uids'] as $key){if(!isset($found[$key])||!is_array($found[$key]))throw new RuntimeException('Unvollständige Identitätssuche.');foreach($found[$key] as $uid)if(!is_int($uid)||$uid<1)throw new RuntimeException('Ungültige Suchidentität.');if(count(array_unique($found[$key]))!==count($found[$key]))throw new RuntimeException('Mehrdeutige Suchidentität.');sort($found[$key],SORT_NUMERIC);}
 $found['epoch_changed']=(int)$d['sent_copy_uidvalidity']>0&&(int)$d['sent_copy_uidvalidity']!==$valid;
 $found['result']=$found['deleted_uids']||count($found['uids'])>1?'conflict':(count($found['uids'])===1?'found':($found['epoch_changed']?'epoch_changed':'missing'));return $found;
}
function gszMailRecoveryFingerprint(array $d):string {return hash('sha256',implode('|',[$d['id'],$d['status'],$d['message_id'],$d['smtp_raw_sha256'],$d['sent_copy_folder'],$d['sent_copy_uidvalidity'],$d['sent_copy_uncertain'],$d['sent_copy']]));}
/** POST-only caller stores this preview in the authenticated session; no raw bytes leave the service. */
function gszMailSentCopyPreview(PDO $pdo,GszMailRemote $remote,int $id):array {
 return gszMailDraftLock($pdo,$id,function()use($pdo,$remote,$id):array{$d=gszMailRecoveryDraft($pdo,$id);$found=gszMailRecoverySearch($remote,$d);return ['draft_id'=>$id,'fingerprint'=>gszMailRecoveryFingerprint($d),'folder'=>$d['sent_copy_folder'],'message_id'=>$d['message_id'],'uncertain'=>(bool)$d['sent_copy_uncertain'],'created'=>time()]+$found;});
}
/** Fresh search always precedes APPEND. An explicit uncertainty acknowledgement is required after any ambiguous attempt. */
function gszMailRecoverSentCopy(PDO $pdo,GszMailRemote $remote,int $admin,int $id,array $preview,bool $acknowledgeUncertain=false):string {
 return gszMailDraftLock($pdo,$id,function()use($pdo,$remote,$admin,$id,$preview,$acknowledgeUncertain):string {
  $d=gszMailRecoveryDraft($pdo,$id);if(($preview['draft_id']??null)!==$id||!is_int($preview['created']??null)||$preview['created']<time()-600||$preview['created']>time()||!hash_equals(gszMailRecoveryFingerprint($d),(string)($preview['fingerprint']??'')))throw new RuntimeException('Vorschau abgelaufen oder Versandstand geändert. Erneut prüfen.');
  $found=gszMailRecoverySearch($remote,$d);if($found['uidvalidity']!==($preview['uidvalidity']??null))throw new RuntimeException('UIDVALIDITY seit Vorschau geändert. Erneut prüfen.');
  if($found['result']==='conflict'||$found['result']==='epoch_changed')throw new RuntimeException('Gelöschte/mehrere Kopien oder geänderte Ordneridentität: manuelle Postfachprüfung erforderlich.');
  if($found['result']==='found'){
   $pdo->prepare("UPDATE mail_drafts SET sent_copy=1,sent_copy_uncertain=0,sent_copy_uidvalidity=?,sent_copy_uid=?,last_error='' WHERE id=?")->execute([$found['uidvalidity'],$found['uids'][0],$id]);gszAudit($pdo,$admin,'mail_sent_copy_found',['draft_id'=>$id,'uidvalidity'=>$found['uidvalidity'],'uid'=>$found['uids'][0]]);return 'found';
  }
  if(($preview['result']??'')!=='missing')throw new RuntimeException('Suchergebnis seit Vorschau geändert. Erneut prüfen.');if($d['sent_copy_uncertain']&&!$acknowledgeUncertain)throw new RuntimeException('Vorheriger Kopierversuch unklar. Mögliche verzögerte Kopie ausdrücklich berücksichtigen.');
  $pdo->prepare('UPDATE mail_drafts SET sent_copy_uncertain=1,sent_copy_uidvalidity=? WHERE id=?')->execute([$found['uidvalidity'],$id]);gszAudit($pdo,$admin,'mail_sent_copy_requested',['draft_id'=>$id]);
  try{$remote->append($d['sent_copy_folder'],$d['smtp_raw']);$after=gszMailRecoverySearch($remote,$d);if($after['uidvalidity']!==$found['uidvalidity']||$after['result']!=='found')throw new RuntimeException('Kopie nicht eindeutig bestätigt.');$pdo->prepare("UPDATE mail_drafts SET sent_copy=1,sent_copy_uncertain=0,sent_copy_uid=?,last_error='' WHERE id=?")->execute([$after['uids'][0],$id]);gszAudit($pdo,$admin,'mail_sent_copy_recovered',['draft_id'=>$id,'uidvalidity'=>$after['uidvalidity'],'uid'=>$after['uids'][0]]);return 'copied';}
  catch(Throwable $e){$pdo->prepare("UPDATE mail_drafts SET last_error='Gesendet-Kopie unklar. Erneut suchen; keine automatische Wiederholung und kein SMTP-Neuversand.' WHERE id=?")->execute([$id]);throw new RuntimeException('Gesendet-Kopie nicht eindeutig bestätigt. Erneut suchen; nicht blind wiederholen.');}
 });
}
function gszReplyRecipients(array $message,string $mode,string $own):array {
 $extract=static function(string $s):array {preg_match_all('/[a-zA-Z0-9.!#$%&\x27*+\/=?^_`{|}~-]+@[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}/',$s,$m);return array_values(array_filter(array_map('trim',$m[0]),fn($v)=>filter_var($v,FILTER_VALIDATE_EMAIL)));};
 $to=$extract(($message['reply_to']??'')?:$message['sender']);$all=$mode==='reply_all'?$extract($message['recipients']):[];$addresses=array_values(array_unique(array_filter([...$to,...$all],fn($s)=>strcasecmp($s,$own)!==0)));if($mode==='forward')$addresses=[];
 return ['to'=>implode(', ',$addresses),'subject'=>($mode==='forward'?'Fwd: ':'Re: ').mb_substr($message['subject'],0,180),'body'=>"\n\n--- Originalnachricht ---\n".$message['body']];
}
function gszMailResolveDraft(PDO $pdo,int $admin,int $id,string $decision,string $reason):void {
 gszMailDraftLock($pdo,$id,function()use($pdo,$admin,$id,$decision,$reason):void {
 $reason=trim($reason);if(!in_array($decision,['sent','not_sent'],true)||$reason===''||mb_strlen($reason)>120)throw new InvalidArgumentException('Manuelle Prüfentscheidung und Notiz erforderlich.');$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM mail_drafts WHERE id=? FOR UPDATE');$q->execute([$id]);$d=$q->fetch();if(!$d||!in_array($d['status'],['sending','uncertain'],true))throw new RuntimeException('Nur unklare Versandstände manuell auflösen.');$pdo->prepare('UPDATE mail_drafts SET status=?,last_error=? WHERE id=?')->execute([$decision==='sent'?'manual_confirmed':'draft','Manuelle Postfachprüfung: '.$reason,$id]);if($decision==='sent'&&$d['reply_message_id'])$pdo->prepare('UPDATE mail_messages SET answered=1 WHERE id=?')->execute([$d['reply_message_id']]);gszAudit($pdo,$admin,'mail_manual_resolution',['draft_id'=>$id,'decision'=>$decision,'reason_hash'=>hash('sha256',$reason)]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
 });
}
